 function showDefinitions(key){const rows=key?definitions.filter(r=>r[1]===key):definitions;openDialog(key?(rows[0]?.[0]||'指标')+' · 统计口径':'指标口径与统计范围',detailHeader('所有比率由同一筛选范围内的分子、分母计算，分母为0时显示0%。明细导出与当前视图使用相同的数据范围。')+`<div class="table-scroll"><table><thead><tr><th>指标</th><th>统计定义</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r[0]}</td><td>${r[2]}</td></tr>`).join('')}</tbody></table></div>`+(key?`<div class="detail-toolbar"><span>当前值：${fmt(model.summary[key])}${['completion','passRate','firstPass'].includes(key)?'%':''}</span><button class="button primary" data-action="kpi-detail" data-key="${key}">查看相关明细${icon('arrow')}</button></div>`:'')+`<div class="notice">课程与考试采用“本期分配任务”批次口径；行为量采用“本期发生”口径；等级、勋章和待审核采用“期末存量”口径。三者应分别解读。零结果检索、附件解析、首页点击等需补充埋点后接入。</div>`,'统计说明');}
