  reset:()=>{state.filters={start:'2026-10-01',end:D.TODAY,region:'all',organization:'all',identity:'all'};$('#start-date').value=state.filters.start;$('#end-date').value=state.filters.end;$('#region').value='all';$('#identity').value='all';updateOrgOptions();$('#filter-error').hidden=true;document.querySelectorAll('[data-period]').forEach(b=>b.classList.toggle('selected',b.dataset.period==='month'));state.table={query:'',category:'all',sort:'',direction:-1,page:1};render();toast('已重置为本月全部学员');},
